/**
 * Errors returned to the app (Kotlin: FfiException.Json / Invalid / Unsupported).
 */
sealed class FfiException(message: String): kotlin.Exception(message) {

    /**
     * A JSON argument did not match the expected model.
     */
        class Json(message: String) : FfiException(message)

    /**
     * The input parsed but the core rejected it.
     */
        class Invalid(message: String) : FfiException(message)

    /**
     * The location cannot run on this platform.
     */
        class Unsupported(message: String) : FfiException(message)


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {

            return when(buf.getInt()) {
            1 -> FfiException.Json(FfiConverterString.read(buf))
            2 -> FfiException.Invalid(FfiConverterString.read(buf))
            3 -> FfiException.Unsupported(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }

    }

    override fun allocationSize(value: FfiException): ULong {
        return 4UL
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Json -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.Invalid -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.Unsupported -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




